-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 creatures are in' AS assertion, count(*) AS got, 4 AS want
  FROM creatures WHERE slug IN ('spiny-creeper', 'titan-raptor', 'tree-prowler', 'quee-la');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('spiny-creeper', 'titan-raptor', 'tree-prowler', 'quee-la');
SELECT 'the creatures carry 13 attacks' AS assertion, count(*) AS got, 13 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('spiny-creeper', 'titan-raptor', 'tree-prowler', 'quee-la');

