INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('spiny-creeper', 'Spiny Creeper', 'animal', 'rifts', 0, 'Animal, considered Anarchist or Miscreant', '{"IQ":"1D4+4","ME":"1D6+6","MA":"1D6","PS":"1D6+12","PP":"1D6+14","PE":"1D6+16","PB":"1D4","Spd":"1D6+34"}', NULL, NULL, '3D6+22', '3D6+PE', 'MEx4', 'Mega-Damage: Main Body 3D6+22; Tail 1D6+10. Ordinary P.S. and P.E. I.Q. is low to medium animal intelligence. Speed is about 25 mph (40 km). In S.D.C. environments: 3D6+6 S.D.C., 2D6+8 Hit Points, A.R. 15; its bite and claw damage is unchanged. Recovers 1D6 M.D.C. per 24 hours.', NULL, 11, '{"attacks":3,"perception":1,"initiative":2,"strike":2,"parry":1,"dodge":4,"roll":4}', 'The +2 to strike is with bites, claws or tail. +4 to save vs poison, +1 to save vs magic and possession. All in addition to possible attribute bonuses.', 'Equivalent skills: Acrobatics 94%, Climb 90%/80%, Identify Plants & Fruit 90%, Land Navigation 95%, Prowl 70%, Tailing 60%, Swim 80%, Wilderness Survival 95%; sniffs out food (human food, grain, carcasses, rotting meat, garbage) by scent 65% up to 3000 feet (914 m), twice that on the wind.', 'Fast and nimble: holds its top speed for up to an hour without a break, and as a born acrobat jumps 14 feet (4.3 m) across or 7 feet (2.1 m) up. Six legs give it the balance to walk beams and tightrope along wires. Fair day vision, good hearing, Nightvision 1000 feet (305 m). Regrows a lost tail, finger or toe within a month, but never a leg or an eye.', 'None.', 'Minor Psychic: Deaden Senses (4), Impervious to Fire (4), Impervious to Poison (4), Telekinetic Leap (8).', '1.5-2 feet (0.45-0.6 m) tall at the shoulder, 3-3.5 feet (0.9-1 m) long from snout to rump, with a tail about as long again', '35-50 lbs (15.7-22.5 kg)', '12-18 years', 'Forests and swamps throughout Dinosaur Swamp, most of all around human and D-Bee settlements and aboard ships such as Horune pirate and slaver vessels; also infests the cities of Atlantis, which may be where it came from', 'Other Spiny Creepers; sometimes runs with other scavengers, Scampers and wild dogs; sometimes a mage''s familiar', 'Humans and most predators', 'None; an animal scavenger.', 'A fox-sized, six-legged alien scavenger, likened to a giant armored rat, whose head-to-tail hide flexes like an armadillo''s; its long crooked teeth and bloodshot green eyes make it hideous. It comes out at night to raid garbage, granaries and stores, and to kill rodents, birds, pets, poultry and young livestock, even human infants. Char is overrun with them, and its shops pay a bounty of two credits a head, usually in goods or services. A minor Mega-Damage creature that mages sometimes take as a familiar. Value: none.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.57-59'),
('titan-raptor', 'Titan Raptor', 'animal', 'rifts', 0, 'Animal predator, considered Miscreant or Diabolic', '{"IQ":"1D6+8","ME":"1D6+9","MA":"1D6+2","PS":"1D6+24","PP":"1D6+19","PE":"1D6+19","PB":"2D6+2","Spd":"2D4+52"}', NULL, NULL, '6D6+80', '2D8', NULL, 'Mega-Damage by location: Head 100; Forearms (2) 3D6+22 each; Hind Legs (2) 4D6+60 each; Tail 3D6+40; Main Body 6D6+80. Females carry 35 more M.D.C. than this. Supernatural P.S. and P.E. I.Q. is high animal intelligence. Average speed 58 (40 mph/64 km). In S.D.C. environments: 6D6 + P.E. attribute number S.D.C., 5D6+50 Hit Points, A.R. 10; its attacks do the same amount as S.D.C. instead of M.D.', NULL, 12, '{"attacks":4,"perception":2,"initiative":3,"strike":3,"parry":3,"dodge":2}', 'Four attacks per melee for males, five for females. Horror Factor 12 for one, 14 for a pack of 4-8, 16 for a pack of 9 or more. +6 to save vs Horror Factor, and fearless in packs of three or more. All in addition to possible attribute bonuses.', 'Track a blood scent 88%; Track Animals and Humanoids by scent and sight 60%; Prowl 65%; Detect Ambush 74%; Climb 65%/30%.', 'Very fast: runs for 8 hours without stopping or tiring, and jumps as far as 40 feet (12.2 m) forward or 22 feet (6.7 m) up, 30% more at full speed. Can go two weeks without food or water unharmed, and eats both live prey and carrion, often taking kills from lone predators and small groups. Smells blood a mile (1.6 km) off. Vulnerability: it cannot swim, and it underrates humanoid foes.', 'None.', 'None.', '11-15 feet (3.3-4.6 m) tall, plus a thin tail as long as the body is tall; females are 20% larger', '300-450 lbs (135-202.5 kg)', '30-35 years', 'Anywhere in Dinosaur Swamp, from forest and mountain valleys to marsh; not known outside the region', 'None beyond its own species; it sometimes preys on its smaller Raptor cousins', 'Other large predators and humanoids; preys on herbivores, livestock and any animal or humanoid that looks vulnerable', 'None; animal.', 'A giant Raptor, 11 to 15 feet tall, built like a Velociraptor with the hooked sickle claw on its foot as its main weapon; nobody knows whether it is a dinosaur from Earth''s past, an alien, or a giant mutation. Packs of 2D4 (seldom over seven or eight, usually 3-5), led by the two largest females, open a hunt by leaping in one after another from different angles and slashing at neck, belly and hamstrings, then close with claws and bites; after three or four melee rounds their teamwork tends to dissolve in bloodlust. Rarer than the smaller Raptors, and hunted on sight by the Alien Rex, Allosaurus, Tyrannosaurus and Razorback Rhino. Unlike Tiger Claw Raptors it does not fear magic. Females lay 1D4+1 eggs a year. Value: none, though the Splugorth like to capture whole packs for their gladiatorial games.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.60-62'),
('tree-prowler', 'Tree Prowler', 'animal', 'rifts', 0, 'Animal predator, considered Miscreant or Diabolic', '{"IQ":"1D6+7","ME":"1D6+12","MA":"2D6","PS":"1D6+23","PP":"1D6+18","PE":"1D6+18","PB":"1D6","Spd":"1D6+12"}', NULL, NULL, '4D6+70', '1D8', 'MEx10', 'Mega-Damage by location: Head 40; Forearms (2) 4D6+80 each; Hind Legs (2) 2D6+20 each; Main Body 4D6+70. Supernatural P.S. I.Q. is high animal intelligence. Speed is on the ground; triple it leaping and swinging through trees. In S.D.C. environments: 4D6+40 S.D.C., 4D6+60 Hit Points, A.R. 8 (A.R. 19 on the forearms); its attacks do the same amount as S.D.C. instead of M.D.', NULL, 11, '{"attacks":4,"perception":2,"initiative":3,"strike":2,"parry":2,"dodge":2}', 'Four attacks per melee for males, five for females. Initiative +5 instead of +3 on a surprise drop from above; strike, parry and dodge bonuses double while hanging from a tree or high surface. +6 to save vs Horror Factor, +2 vs poison, +2 vs psionic attack. All in addition to possible attribute bonuses.', 'Track a blood scent 75% (smells blood up to half a mile/0.8 km); Acrobatics 75%; Climb 95%/85%; Detect Ambush 90%; Gymnastics 92%; Land Navigation 80%; Prowl 80%; Swim 60%; Wilderness Survival 98%.', 'Slow and exposed on the ground, swift in the trees: jumps 20 feet (6.1 m) across or 12 feet (3.6 m) up, swings 20 feet (6.1 m) up or 40 feet (12.2 m) across, and climbs and swings for five hours without tiring. Drops from up to 150 feet (45.7 m) onto its feet unhurt and can go straight into an attack; a drop or pounce costs one melee action. Goes a week without food or water after a meal, kills everything it eats (never carrion) and carries the kill up high to feed. Eyeless: heat receptors in its mouth and tongue give it a detailed thermal picture, a 180 degree sweep to 2000 feet (610 m) with the mouth wide open, which beats passive nightvision optics in the dark; so the mouth is always a little open. See psionics too.', 'None.', 'Major Psychic: Bio-Regenerate (self; 6, works on M.D.C.), Detect Psionics (6), Psychic Purification (8), Stop Bleeding (4), Deaden Senses (4), Presence Sense (4), Resist Fatigue (4), Sense Time (2).', '4-5 feet (1.2-1.5 m) tall at the shoulder, 5-6 feet (1.5-1.8 m) long from snout to rump; the forearms reach 6-7 feet (1.8-2.1 m)', '300-500 lbs (135-225 kg)', '30-40 years', 'Mainly forests, city ruins and caves with high places to climb, hang and strike from; rare in the marsh, found mostly in the forests of Georgia, the Carolinas and the Appalachian Mountains', 'None beyond its own species', 'Other predators and humanoids; preys on herbivores, livestock and large animals such as deer, dogs and humanoids', 'None; animal.', 'A Rift-born ambusher of the treetops that looks like a big, hairless, carnivorous sloth or ape but moves like a panther. Its bronze M.D.C. hide has a plaster-like texture; the eyeless head is nearly all toothed mouth, wide enough to take a human head or a man''s shoulder; the gorilla-sized arms carry bone-and-pad armor on the forearms and end in two hooked fingers and a thumb, and the small hind feet are prehensile. It hangs upside down from a low branch to grab prey with one arm and rake throat and belly with the other, or drops onto a victim from high above. Hunts alone like a leopard, sometimes with its mate and 1D4 young, sleeping by day and hunting at night; one seen gaping as if yawning is scanning for prey. Value: none, though the Splugorth sometimes use them as arena monsters.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.62-64'),
('quee-la', 'Quee-la', 'alien humanoid', 'rifts', 0, 'Scrupulous', '{"IQ":"20","ME":"11","MA":"19","PS":"12","PP":"9","PE":"10","PB":"10","Spd":"18"}', NULL, NULL, NULL, NULL, NULL, 'The book prints one individual with fixed attributes, age 30, and no Hit Points, S.D.C., P.P.E. or I.S.P.', NULL, NULL, '{"attacks":3,"perception":2}', '+2 to save vs mind control and possession, plus any bonuses from skills. Three attacks per melee; she has no combat skills.', '11th level Scientist: Astrophysics 90%, Basic Electronics 90%, Basic Mechanics 70%, Computer Operation 90%, Mathematics: Advanced and Basic 98% each, Photography 98%, Radio: Basic 90%, Sensory Equipment 90%, TV/Video 80%; speaks American 98%.', 'Much like a human apart from her innate psionics and an instinctive Swim of 66%. Empathic Language Mastery (20 I.S.P.), an ability every member of her race has: by Empathy, Telepathy and hard study she learns a new language to 40% comprehension in 24 hours, improving by 10% a day after that, and reads it at a base 60%, gaining 2% for each month she keeps studying and practicing.', 'None; she does not believe magic is real.', 'Empathy (4), Empathic Transmission (6), Mask P.P.E. (4), Meditation (0), Sense Time (2), Telepathy (4), and Empathic Language Mastery (20; see natural abilities). The Quick Find lists her under Alien/D-Bee, not under psionics; her block prints these.', 'Roughly human, 5 feet 6 inches (1.6 m)', NULL, NULL, 'Stranded in Dinosaur Swamp, a traveler from another world', 'Any who will help her; the six co-workers she arrived with are lost, eaten or still captive', 'The slavers who captured her and hold the dimensional travel device that could send her home', '11th level Scientist; no combat skills. Equipment: none, everything she had was taken or lost.', 'An intelligent, talking dinosaur-like D-Bee from an adventure seed (a 28% result): humanoid in shape on chicken-like legs, with a small round head, a flat wide nose, small round ears, a slit of a mouth, large dog-like eyes and human-like hands with four fingers and a thumb. A scientist whose experiment in dimensional travel went wrong and dropped her and six co-workers into the jungle: two vanished, three were eaten, and she and the last were caught by slavers and dragged off to meet someone she calls Horoon. She escaped in a storm and is found injured, exhausted and leaning on a branch for a crutch, 27 days on Rifts Earth, six of them as a captive. She asks for help recovering the device, and understands if it is refused.', 'Rifts World Book 27: Adventures in Dinosaur Swamp p.133-134');
